TaxInvoiceBulk.ListOfTaxInvoice:
{{- $seller := .Doc.seller_nitku}}
{{- range .Related.invoices}}{{$inv := .}}
{{- $fx := and .currency (ne .currency "IDR")}}
{{- $fee := and .ppn_base (ne (dec .ppn_base 2) (dec .dpp 2))}}
{{- $s := "0"}}{{$n := "0"}}{{range .items}}{{if not (and $fee .ppn_exclude)}}{{$n = add $n 1}}{{if $fx}}{{$s = add $s .amount_fx_idr}}{{else}}{{$s = add $s .amount}}{{end}}{{end}}{{end}}
{{- $r := sub $s .ppn_base}}{{$k := "0"}}{{$acc := "0"}}

			{{isodate .posting_date}}
			Normal
			{{.efaktur_code}}



			{{.name}}{{if .dp_invoice}}; uang muka {{.dp_invoice}}{{end}}{{if $fee}}; upah tenaga kerja di luar DPP (PMK 83/2012){{end}}

			{{$seller}}
			{{.buyer_tin}}
			{{.buyer_id_type}}
			{{.buyer_country}}
			{{if ne .buyer_id_type "TIN"}}{{.buyer_doc_no}}{{end}}
			{{.buyer_name}}
			{{.buyer_address}}
			{{.buyer_email}}
			{{.buyer_idtku}}

{{- range $i, $l := .items}}{{if not (and $fee $l.ppn_exclude)}}{{$k = add $k 1}}
{{- $b := $l.amount}}{{$p := $l.rate}}{{if $fx}}{{$b = $l.amount_fx_idr}}{{$p = round (mul $l.rate_fx $inv.exchange_rate) 2}}{{end}}
{{- $q := round $l.qty 2}}
{{- $tb := round (sub $b (div (mul $r $b) $s)) 2}}{{if eq $k $n}}{{$tb = sub $inv.ppn_base $acc}}{{end}}{{$acc = add $acc $tb}}
{{- $otb := round (div (mul $tb $inv.dpp_num) $inv.dpp_den) 2}}
{{- /* Line amounts are whole rupiah while Price x Qty has 2 decimals, so Price x Qty can fall a few sen under TaxBase:
  then Price is raised to TaxBase / Qty (rounded up to the sen) and TotalDiscount stays 0 or a few sen, never negative
  (audit pajak 7 Nov D1). */}}
{{- if eq (slice (dec (sub (round (mul $p $q) 2) $tb) 2) 0 1) "-"}}{{$p = round (div $tb $q) 2}}{{if eq (slice (dec (sub (round (mul $p $q) 2) $tb) 2) 0 1) "-"}}{{$p = add $p "0.01"}}{{end}}{{end}}

					{{$l.coretax_opt}}
					{{$l.coretax_code}}
					{{if $l.description}}{{$l.description}}{{else}}{{$l.item}}{{end}}
					{{$l.coretax_unit}}
					{{dec $p 2}}
					{{dec $q 2}}
					{{dec (sub (round (mul $p $q) 2) $tb) 2}}
					{{dec $tb 2}}
					{{dec $otb 2}}
					{{dec $inv.tax_rate 2}}
					{{dec (round (div (mul $otb $inv.tax_rate) 100) 2) 2}}
					0
					0

{{- end}}{{end}}


{{- end}}
